package com.kovian.finance.ai.api; import com.kovian.finance.ai.application.*; import com.kovian.finance.ai.domain.*; import com.kovian.finance.transaction.repository.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/v1/ai/finance") public class FinancialInsightController {final FinancialInsightService service; FinancialInsightController(FinancialTransactionRepository t){service=new FinancialInsightService(t);} @GetMapping("/insights") public List<FinancialInsight> insights(@RequestParam UUID ownerId,@RequestParam LocalDate from,@RequestParam LocalDate to){if(to.isBefore(from))throw new IllegalArgumentException("Invalid date range");return service.analyze(ownerId,from,to);}}